from __future__ import print_function
from builtins import object
from taf.sw.syslog import syslog as ute_syslog
from taf.sw.syslog.exception import ParsingError
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.log_collection.exceptions import *
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class SyslogOperations(object):
    INSTANCE = None

    def __init__(self):
        self.config = ConfigHandler.get_config()
        self.syslog = ute_syslog()

    @classmethod
    def get_instance(cls):
        if not cls.INSTANCE:
            cls.INSTANCE = SyslogOperations()
        return cls.INSTANCE

    def start_syslog(self, log_dir, log_name, ip, ports, host_ip, file_limit, add_line_number,
                     alias, **kwargs):
        print("start", alias)
        return self.syslog.start_syslog(log_dir, log_name, ip, ports, host_ip, file_limit,
                                        add_line_number, alias=alias, **kwargs)

    def stop_syslog(self, alias):
        return self.syslog.stop_syslog(alias=alias)

    def analyse_syslog(self, analysis, alias):
        ignore = None
        evalValue = get_config_variable(["syslog_analysis", analysis, "eval"])
        regexps = get_config_variable(["syslog_analysis", analysis, "regexp"])
        try:
            ignore = get_config_variable(["syslog_analysis", analysis, "ignore"])
            if ignore and not isinstance(ignore, list):
                raise ErrorStringFound("Syslog ignore attribute is expected to be a list but "
                                       "got {}.".format(type(ignore)))
        except Exception:
            pass
        if evalValue == "get_count":
            return self._count_syslog_messages(regexps, ignore, alias=alias)
        # try:
        # 	total_matched = self._count_syslog_messages(regexps, alias=alias)
        # 	if isinstance(ignore, list):
        # 		for item in ignore:
        # 			ignore_match = "("+regexps+")*("+item+")"
        # 			ignored_match = self._count_syslog_messages(ignore_match, alias=alias)
        # 			total_matched = total_matched - ignored_match
        # except AttributeError:
        # 	logger.debug("Nothing to ignore from syslog. Just capture regexp {}".format(regexps))
        # 	return self._count_syslog_messages(regexps, alias=alias)
        # return total_matched
        elif evalValue == "should_exist":
            for regexp in regexps:
                self._message_should_exist_in_syslog(regexp, alias)
        elif evalValue == "should_not_exist":
            for regexp in regexps:
                self._message_should_not_exist_in_syslog(regexp, alias)
        elif evalValue == "wait_for_message":
            return self._wait_for_message(alias)

    def _count_syslog_messages(self, regexp, ignore, alias):
        if ignore is None:
            return self.syslog.count_syslog_messages(regexp, alias=alias)
        else:
            total_matched = self.syslog.count_syslog_messages(regexp, alias=alias)
            for item in ignore:
                ignore_match = "(" + regexp + ")*(" + item + ")"
                ignored_match = self.syslog.count_syslog_messages(ignore_match, alias=alias)
                total_matched = total_matched - ignored_match
            return total_matched

    def _message_should_exist_in_syslog(self, regexp, alias):
        return self.syslog.message_should_exist_in_syslog_file(regexp, alias=alias)

    def _message_should_not_exist_in_syslog(self, regexp, alias):
        try:
            out = self.syslog.store.get(alias=alias)['operator'].message_exists(regexp)
        except ParsingError as e:
            logger.info("Parsing complete for error string: " + regexp)
        except Exception as e:
            raise e
        else:
            raise ErrorStringFound(
                "Error String matching regexp ({}) found: ({})".format(regexp, out))

    def _wait_for_message(self, alias):
        # TBD
        pass
